-- Telegram account linking + per-chat throttling (plan 4.7).
--
-- The bot is a webhook Edge Function authenticated by the
-- `X-Telegram-Bot-Api-Secret-Token` header. It uses the service role, so these
-- tables have RLS enabled and no client policies: only the function reads or
-- writes them. Link codes are one-time, short-lived, and generated by the
-- `telegram-link` function for a signed-in profile.

create table if not exists public.telegram_link_codes (
  code text primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  expires_at timestamptz not null,
  used_at timestamptz,
  created_at timestamptz not null default now(),
  constraint telegram_link_codes_code_format check (code ~ '^[A-Z0-9]{8,16}$')
);

create index if not exists telegram_link_codes_user_id_idx
  on public.telegram_link_codes (user_id);

alter table public.telegram_link_codes enable row level security;

-- One rolling row per chat. `window_start` is the start of the fixed window;
-- a new window resets the counter atomically inside the function below.
create table if not exists public.telegram_rate_windows (
  chat_id bigint primary key,
  window_start timestamptz not null,
  requests integer not null default 0 check (requests >= 0)
);

alter table public.telegram_rate_windows enable row level security;

-- Counts one bot message for `p_chat_id` and returns whether it is within
-- `p_limit` for the current fixed window. `p_window_seconds` is clamped so a
-- bad caller cannot create an effectively unlimited window.
create or replace function public.consume_telegram_message(
  p_chat_id bigint,
  p_limit integer,
  p_window_seconds integer
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_window integer := greatest(10, least(coalesce(p_window_seconds, 60), 3600));
  v_start timestamptz;
  v_count integer;
begin
  if p_chat_id is null or p_limit is null or p_limit < 0 then
    raise exception 'invalid_arguments' using errcode = '22023';
  end if;

  v_start := to_timestamp(
    floor(extract(epoch from now()) / v_window) * v_window
  );

  insert into public.telegram_rate_windows as w (chat_id, window_start, requests)
  values (p_chat_id, v_start, 1)
  on conflict (chat_id) do update
    set requests = case
          when w.window_start = excluded.window_start then w.requests + 1
          else 1
        end,
        window_start = excluded.window_start
  returning requests into v_count;

  return v_count <= p_limit;
end;
$$;

revoke all on function public.consume_telegram_message(bigint, integer, integer) from public;
revoke all on function public.consume_telegram_message(bigint, integer, integer) from anon;
revoke all on function public.consume_telegram_message(bigint, integer, integer) from authenticated;

-- Consume a one-time link code and attach the chat to the profile. Returns the
-- linked profile id, or null when the code is unknown/expired/already used.
create or replace function public.consume_telegram_link_code(
  p_code text,
  p_chat_id bigint,
  p_username text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid;
begin
  if p_code is null or p_chat_id is null then
    return null;
  end if;

  update public.telegram_link_codes
  set used_at = now()
  where code = upper(btrim(p_code))
    and used_at is null
    and expires_at >= now()
  returning user_id into v_user_id;

  if v_user_id is null then
    return null;
  end if;

  update public.profiles
  set telegram_chat_id = p_chat_id,
      telegram_username = nullif(btrim(coalesce(p_username, '')), ''),
      updated_at = now()
  where id = v_user_id;

  return v_user_id;
end;
$$;

revoke all on function public.consume_telegram_link_code(text, bigint, text) from public;
revoke all on function public.consume_telegram_link_code(text, bigint, text) from anon;
revoke all on function public.consume_telegram_link_code(text, bigint, text) from authenticated;

-- The bot authenticates a linked profile without a browser session, so it
-- cannot call `get_my_usage` (that reads auth.uid()). This service-only twin
-- returns the same shape for the linked user.
create or replace function public.get_user_usage_for_service(p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  with me as (
    select p.id, p.plan_id, pl.features, pl.monthly_budget_micro_usd
    from public.profiles p
    join public.plans pl on pl.id = p.plan_id
    where p.id = p_user_id
  ),
  daily as (
    select c.feature, c.requests
    from public.ai_usage_counters c
    where c.user_id = p_user_id
      and c.period_kind = 'day'
      and c.period_start = current_date
  ),
  monthly as (
    select coalesce(sum(c.cost_micro_usd), 0)::bigint as used
    from public.ai_usage_counters c
    where c.user_id = p_user_id
      and c.period_kind = 'month'
      and c.period_start = date_trunc('month', current_date)::date
  )
  select jsonb_build_object(
    'plan_id', me.plan_id,
    'daily', coalesce((
      select jsonb_object_agg(
        f.feature,
        jsonb_build_object(
          'limit', (me.features ->> f.feature)::integer,
          'used', coalesce(d.requests, 0),
          'remaining', case
            when (me.features ->> f.feature)::integer < 0 then null
            else greatest(0, (me.features ->> f.feature)::integer - coalesce(d.requests, 0))
          end
        )
      )
      from jsonb_object_keys(me.features) as f(feature)
      left join daily d on d.feature = f.feature
    ), '{}'::jsonb),
    'monthly', jsonb_build_object(
      'budget_micro_usd', me.monthly_budget_micro_usd,
      'used_micro_usd', monthly.used,
      'remaining_micro_usd', case
        when me.monthly_budget_micro_usd < 0 then null
        else greatest(0, me.monthly_budget_micro_usd - monthly.used)
      end
    ),
    'resets_at', (date_trunc('day', now()) + interval '1 day')::timestamptz
  )
  from me, monthly;
$$;

revoke all on function public.get_user_usage_for_service(uuid) from public;
revoke all on function public.get_user_usage_for_service(uuid) from anon;
revoke all on function public.get_user_usage_for_service(uuid) from authenticated;
